System.register("chunks:///_virtual/MonthlyCatalog.ts",[],(function(t){return{execute:function(){t("MONTHLY_CARDS",[{id:"oct-c1-1",chapter:1,name:"胡萝卜提灯",rarity:1,story:"小兔提着暖暖的灯，等每一位朋友回家。"},{id:"oct-c1-2",chapter:1,name:"南瓜小灯",rarity:1,story:"小狐狸把第一簇烛光，藏进圆圆的南瓜里。"},{id:"oct-c1-3",chapter:1,name:"门廊等你",rarity:1,story:"招财在门口留了一小片光，晚归也不会走错路。"},{id:"oct-c1-4",chapter:1,name:"窗边微光",rarity:1,story:"窗外的月亮很远，窗里的灯却刚好暖到爪尖。"},{id:"oct-c1-5",chapter:1,name:"林间灯路",rarity:1,story:"一盏接一盏的小灯，把刺猬的影子送到家门口。"},{id:"oct-c1-6",chapter:1,name:"晚安灯会",rarity:2,story:"最后一盏灯亮起来时，大家轻轻说了声晚安。"},{id:"oct-c2-1",chapter:2,name:"糖果敲门",rarity:1,story:"敲三下门，会得到糖果，还是一个温暖的拥抱？"},{id:"oct-c2-2",chapter:2,name:"枫糖饼干",rarity:1,story:"小狐狸烤的枫叶不会飘走，只会香香地留在掌心。"},{id:"oct-c2-3",chapter:2,name:"口袋惊喜",rarity:1,story:"刺猬没有说话，口袋里的糖纸却先笑出了声。"},{id:"oct-c2-4",chapter:2,name:"小熊分糖",rarity:1,story:"小熊把最大的糖留给朋友，自己也笑得甜甜的。"},{id:"oct-c2-5",chapter:2,name:"南瓜茶点",rarity:2,story:"招财摆好了茶点，还为晚到的朋友多留了一份。"},{id:"oct-c2-6",chapter:2,name:"甜梦来客",rarity:2,story:"装扮可以不一样，口袋里装的都是想送给你的甜。"},{id:"oct-c3-1",chapter:3,name:"第一杯可可",rarity:1,story:"杯子还很烫，小熊决定先闻一闻今晚的幸福。"},{id:"oct-c3-2",chapter:3,name:"炉边软毯",rarity:1,story:"毯子分给你一半，小兔就暖和了两倍。"},{id:"oct-c3-3",chapter:3,name:"栗子香气",rarity:1,story:"栗子香飘过门缝，连月亮都像往窗边挪了一点。"},{id:"oct-c3-4",chapter:3,name:"茶壶咕嘟",rarity:2,story:"茶壶咕嘟一声，像是在替大家答应明晚再来。"},{id:"oct-c3-5",chapter:3,name:"暖炉圆桌",rarity:2,story:"炉火轻轻跳着，谁的故事都有人认真听。"},{id:"oct-c3-6",chapter:3,name:"睡前悄悄话",rarity:2,story:"招财把声音放得很轻，好让小兔带着晚安入梦。"},{id:"oct-c4-1",chapter:4,name:"一片晚安",rarity:1,story:"刺猬在最平整的枫叶上，只写了四个字：明天见呀。"},{id:"oct-c4-2",chapter:4,name:"小小邮差",rarity:1,story:"信袋有一点重，可每一封都有人等着呢。"},{id:"oct-c4-3",chapter:4,name:"门前信箱",rarity:2,story:"信箱打开的声音，比风吹过树叶还要让人期待。"},{id:"oct-c4-4",chapter:4,name:"寄给月亮",rarity:2,story:"猫头鹰把信寄给月亮，请它替自己照顾远方的朋友。"},{id:"oct-c4-5",chapter:4,name:"枫叶回信",rarity:2,story:"两封回信一起到达，招财读了又读，舍不得收起来。"},{id:"oct-c4-6",chapter:4,name:"夜游邮车",rarity:3,story:"小车慢慢经过每一扇窗，把想念送到亮着灯的地方。"},{id:"oct-c5-1",chapter:5,name:"出发的铃声",rarity:1,story:"小鹿轻轻晃了晃铃铛，今夜的散步就这样开始了。"},{id:"oct-c5-2",chapter:5,name:"星星纸灯",rarity:2,story:"猫头鹰折出一颗纸星星，决定把它借给没有月光的路。"},{id:"oct-c5-3",chapter:5,name:"枫叶小径",rarity:2,story:"小兔放慢脚步，等刺猬把落在身后的枫叶数完。"},{id:"oct-c5-4",chapter:5,name:"月光路牌",rarity:2,story:"小狐狸站在路牌旁，替还没赶上的伙伴留着灯。"},{id:"oct-c5-5",chapter:5,name:"森林巡游",rarity:3,story:"灯光连成短短一条河，悄悄流过睡着的森林。"},{id:"oct-c5-6",chapter:5,name:"回家的一盏灯",rarity:3,story:"转过最后一个弯，招财和那盏熟悉的灯都在等你。"},{id:"oct-c6-1",chapter:6,name:"南瓜浓汤",rarity:2,story:"小熊搅了搅浓汤，想把秋天的暖意也盛进碗里。"},{id:"oct-c6-2",chapter:6,name:"月光餐布",rarity:2,story:"桌布铺平了，今晚的月光也有了可以坐下的地方。"},{id:"oct-c6-3",chapter:6,name:"出炉南瓜派",rarity:2,story:"派刚出炉，小狐狸提醒了三次小心烫，自己却最想先尝。"},{id:"oct-c6-4",chapter:6,name:"留给你的座位",rarity:2,story:"招财把椅子挪近暖灯，说这个位置一直给你留着。"},{id:"oct-c6-5",chapter:6,name:"月下团圆",rarity:3,story:"大家把最喜欢的一口分出去，桌上的幸福反而更多了。"},{id:"oct-c6-6",chapter:6,name:"灯火晚安",rarity:3,story:"最后一扇窗合上以前，小屋又轻轻说了一遍晚安。"}])}}}));

